# -*- coding: utf-8 -*-
"""Full quality pass for 2 Kings: plain summaries with outline citations, exact KJV quotes,
roles without citations, distinct Original Audience text, KJV facts and spellings in notes and story.

Run once, after review_2_kings.py.
"""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def load(path):
    with path.open(encoding="utf-8") as source:
        return json.load(source)


def save(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def replace_once(text, old, new, label):
    if text.count(old) == 0 and text.count(new) >= 1:
        return text
    if text.count(old) != 1:
        raise SystemExit(f"{label}: {text.count(old)} matches for {old!r}")
    return text.replace(old, new)


