# (chapter, note title, old text, new text) edits to cultural notes.
CULTURE = [
    (23, "Tophet", "Tophet in the valley of Hinnom was where children", "Topheth in the valley of Hinnom was where children"),
    (24, "Babylonian Chronicle", "captured ‘the city of Judah’ in his seventh year", "captured the city of Judah in his seventh year"),
]


def apply_chapter_context():
    path = ROOT / "chapter_context" / "12_2_kings.json"
    data = load(path)
    for number, text in AUDIENCE.items():
        data[f"2 Kings {number}"]["audience"] = text
    for number, title, old, new in CULTURE:
        hits = [n for n in data[f"2 Kings {number}"]["culture"] if n["title"] in (title, title + "h")]
        if len(hits) != 1:
            raise SystemExit(f"2 Kings {number}: {len(hits)} notes titled {title!r}")
        hits[0]["text"] = replace_once(hits[0]["text"], old, new, f"2 Kings {number} {title}")
        if number == 23:
            hits[0]["title"] = "Topheth"
    for key, entry in data.items():
        if not key.startswith("2 Kings"):
            continue
        for old, new in (("Beth-shemesh", "Bethshemesh"), ("Ramoth-gilead", "Ramothgilead"), ("Jabesh-gilead", "Jabeshgilead")):
            entry["audience"] = entry["audience"].replace(old, new)
            for note in entry["culture"]:
                note["title"] = note["title"].replace(old, new)
                note["text"] = note["text"].replace(old, new)
    save(path, data)
    print(f"Updated {path.relative_to(ROOT)}")


def apply_historical_moments():
    path = ROOT / "historical_moments" / "05_kings.json"
    data = load(path)
    data["2 Kings 4"] = replace_once(data["2 Kings 4"], "During Elisha’s ministry", "During Elisha's ministry", "2 Kings 4 moment")
    data["2 Kings 8"] = replace_once(data["2 Kings 8"], "calls Hazael ‘son of a nobody,’ a usurper.", "calls Hazael the son of a nobody, a usurper.", "2 Kings 8 moment")
    data["2 Kings 10"] = replace_once(data["2 Kings 10"], "destroys Ahab’s house", "destroys Ahab's house", "2 Kings 10 moment")
    data["2 Kings 20"] = replace_once(data["2 Kings 20"], "Merodachbaladan of Babylon", "Berodachbaladan of Babylon", "2 Kings 20 moment")
    save(path, data)
    print(f"Updated {path.relative_to(ROOT)}")


def apply_book_overview():
    path = ROOT / "book_overviews" / "02_early_history.json"
    data = load(path)
    book = data["2 Kings"]
    book["author"] = replace_once(
        book["author"],
        "Jeremiah is the traditional author, though 2 Kings does not name its writer.",
        "1 and 2 Kings were one book. Jewish tradition credits Jeremiah as the author, though 2 Kings does not name its writer.",
        "author",
    )
    book["audience"] = replace_once(
        book["audience"],
        "Israel and later readers reflecting on the fall of Israel and Judah.",
        "Israelites in exile, who needed to understand why Israel and Judah fell and whether the LORD's promise to David still stood.",
        "audience",
    )
    for figure in book["keyFigures"]:
        if figure["name"] == "Naaman":
            figure["description"] = replace_once(figure["description"], "An Aramean army commander healed of a skin disease after washing in the Jordan.", "A Syrian army commander healed of leprosy after washing in the Jordan.", "Naaman")
    save(path, data)
    print(f"Updated {path.relative_to(ROOT)}")


STORY_FIXES = [
    ("Then, on the road to Bethel, a gang of young men comes out of the city and mocks him:", "Then, on the road to Bethel, a crowd of boys, called \"little children\" in the KJV, comes out of the city and mocks him:"),
    ("They are mocking him to go up to heaven as Elijah did.", "Many readers think they are mocking him to go up to heaven as Elijah did."),
    ("Elisha sends a young prophet to Ramoth-gilead to anoint Jehu", "Elisha sends a young prophet to Ramothgilead to anoint Jehu"),
    ("puts the crown on his head, and gives him a copy of God's law.", "puts the crown on his head, and gives him the testimony, probably a copy of God's law."),
    ("These mixed people became the ancestors of the Samaritans in Jesus' day.", "Many believe these mixed people became the ancestors of the Samaritans in Jesus' day."),
    ("Hezekiah is flattered and shows them everything", "Hezekiah is pleased and shows them everything"),
    ("Then messengers come from Merodachbaladan, the king of Babylon,", "Then messengers come from Berodachbaladan, the king of Babylon,"),
]


def apply_story_fixes():
    path = ROOT / "book_content" / "03_later_history.md"
    text = path.read_text(encoding="utf-8")
    start = text.index("# 2 Kings")
    end = text.find("\n# ", start + 5)
    end = len(text) if end < 0 else end + 1
    section = text[start:end]
    for old, new in STORY_FIXES:
        section = replace_once(section, old, new, f"story {old[:40]!r}")
    path.write_text(text[:start] + section + text[end:], encoding="utf-8")
    print(f"Updated {path.relative_to(ROOT)}")


if __name__ == "__main__":
    apply_chapter_insights()
    apply_chapter_context()
    apply_historical_moments()
    apply_book_overview()
    apply_story_fixes()
